.plugin-kanban-overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.55); z-index: 9000; display: flex; align-items: center; justify-content: center; }
.plugin-kanban-panel { background: var(--surface, #fff); color: var(--text, #111); border: 1px solid var(--border, #ccc); border-radius: 8px; width: min(960px, 92vw); max-height: 85vh; overflow: auto; padding: 16px; }
.plugin-kanban-title { font-weight: 700; font-size: 18px; margin-bottom: 8px; }
.plugin-kanban-close { float: right; }
.plugin-kanban-columns { display: flex; gap: 12px; align-items: flex-start; }
.plugin-kanban-column { flex: 1; min-width: 0; background: var(--bg, #fafafa); border: 1px solid var(--border, #ccc); border-radius: 6px; padding: 8px; }
.plugin-kanban-column-title { font-weight: 700; font-size: 12px; letter-spacing: 0.08em; margin-bottom: 8px; color: var(--text-muted, #666); }
.plugin-kanban-card { border: 1px solid var(--border, #ccc); border-radius: 4px; padding: 8px; margin-bottom: 8px; background: var(--surface, #fff); }
.plugin-kanban-move { display: block; margin-top: 6px; font-size: 11px; }

