var STATUSES = ['todo', 'doing', 'done'];
var overlayHandle = null;

function statusOf(card) {
  var tags = card.tags || [];
  for (var i = 0; i < STATUSES.length; i++) {
    if (tags.indexOf(STATUSES[i]) !== -1) return STATUSES[i];
  }
  return 'todo';
}

async function moveCard(card, status) {
  var tags = (card.tags || []).filter(function(t) { return STATUSES.indexOf(t) === -1; });
  tags.push(status);
  await ctx.api.data.setTags(card.id, tags);
  await renderBoard();
}

async function buildColumns() {
  var cards = await ctx.api.data.listCards();
  return STATUSES.map(function(status, idx) {
    var colCards = cards.filter(function(c) { return statusOf(c) === status; }).map(function(card) {
      var children = [ctx.h('div', {}, card.title || '(Untitled)')];
      if (idx < STATUSES.length - 1) {
        children.push(ctx.h('button', {
          className: 'btn plugin-kanban-move',
          onclick: function() { moveCard(card, STATUSES[idx + 1]); }
        }, 'Move to ' + STATUSES[idx + 1]));
      }
      return ctx.h('div', { className: 'plugin-kanban-card' }, children);
    });
    return ctx.h('div', { className: 'plugin-kanban-column' }, [
      ctx.h('div', { className: 'plugin-kanban-column-title' }, status.toUpperCase())
    ].concat(colCards));
  });
}

// The overlay is injected on open and removed on close (rather than
// toggling a hidden real element) since a sandboxed plugin only ever
// describes DOM via vnodes — see docs/architecture/PLUGIN_SYSTEM.md
// "Building UI: ctx.h and the vnode model".
async function renderBoard() {
  var columns = await buildColumns();
  var vnode = ctx.h('div', { className: 'plugin-kanban-overlay' }, [
    ctx.h('div', { className: 'plugin-kanban-panel' }, [
      ctx.h('button', { className: 'btn plugin-kanban-close', onclick: closeBoard }, 'Close'),
      ctx.h('div', { className: 'plugin-kanban-title' }, 'Kanban Board'),
      ctx.h('div', { className: 'plugin-kanban-columns' }, columns)
    ])
  ]);
  if (!overlayHandle) {
    overlayHandle = await ctx.api.ui.inject('body', vnode, 'append');
  } else {
    await overlayHandle.update(vnode);
  }
}

async function closeBoard() {
  if (overlayHandle) {
    await overlayHandle.remove();
    overlayHandle = null;
  }
}

var openBtn = ctx.h('button', { className: 'btn plugin-kanban-btn', onclick: renderBoard }, 'Board');
await ctx.api.ui.inject('.header', openBtn, 'append');

ctx.logger.info('Kanban board ready');
